const docs = $json.data?.events?.edges?.[0]?.node?.documents || [];

// Read swappable settings from the Config node
const cfg = $('Config').first().json;
const allowedExts = (cfg.allowedFileExtensions || 'xlsx,xls')
  .split(',').map(e => e.trim().toLowerCase());
const firstChoice = (cfg.documentNameFirstChoice || '').toLowerCase();
const secondChoice = (cfg.documentNameSecondChoice || '').toLowerCase();

// Find spreadsheet documents attached to the event
const excelDocs = docs.filter(d => {
  const ext = (d.fileExtension || '').toLowerCase();
  const mime = (d.mimeType || '').toLowerCase();
  return allowedExts.includes(ext) ||
    mime.includes('spreadsheetml') || mime.includes('ms-excel');
});

// prefer first choice name, then second choice, then first spreadsheet found
const pick =
  (firstChoice && excelDocs.find(d => (d.name || '').toLowerCase().includes(firstChoice))) ||
  (secondChoice && excelDocs.find(d => (d.name || '').toLowerCase().includes(secondChoice))) ||
  excelDocs[0] ||
  null;

$json.selectedDocument = pick;
$json.selectedDocumentId = pick?.id || null;

return $json;

