=mutation createContacts ($contactCreateInput:[ContactCreateInput]!) {
  contact{
    createBatch(input:$contactCreateInput){
      contact{
        id
        personalName{
          firstName
          lastName
        }
        account{
          id
          name
        }
        emailAddress
      }
      errors{
        label
        message
        value
      }
    }
  }
}

