  query: `mutation updateEvent($eventId: ID!, $internalNotes: String) {
  event {
    update(eventId: $eventId, input: { internalNotes: $internalNotes }) {
      errors {
        label
        message
        value
      }
      event {
        id
        legacyId
        internalNotes
      }
    }
  }
}`,
  variables: {
    eventId: $json.data.events.edges[0].node.id,
    internalNotes: ($json.data.events.edges[0].node.internalNotes ?? '')
      + '<p>REGISTER LEARNERS VIA SPREADSHEET: '
      + [].concat($('Combine status messages').item.json.message ?? [], $('Combine status messages').item.json.Message ?? []).join(', ')
      + '</p>'
  }
}) }}

